cat > target_wrong.c <<'EOF'
#include <stddef.h>
int LLVMFuzzerTestOneInput(const char *data, size_t size) { (void)data; (void)size; return 0; }
EOF
# Mimic libFuzzer driver: declares/calls through CORRECT prototype
cat > driver.c <<'EOF'
#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
extern int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);
typedef int (*CB)(const uint8_t*, size_t);
int main(int argc, char** argv){
  CB cb = LLVMFuzzerTestOneInput;
  unsigned char b = 0;
  return cb(&b, 1);
}
EOF
clang -fsanitize=function target_wrong.c driver.c -o wrongrun 2>&1 | head -5
./wrongrun; echo "wrong-prototype exit=$?"
# correct prototype control
cat > target_right.c <<'EOF'
#include <stdint.h>
#include <stddef.h>
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) { (void)data; (void)size; return 0; }
EOF
clang -fsanitize=function target_right.c driver.c -o rightrun 2>&1 | head -5
./rightrun; echo "right-prototype exit=$?"
# also gcc ubsan function check
gcc-9 -fsanitize=undefined target_wrong.c driver.c -o wrongrun_gcc 2>&1|head -2; ./wrongrun_gcc; echo "gcc-wrong exit=$?"

